import numpy as np, math
from scipy import ndimage
from PIL import Image
im = Image.open('images/fig_084.png').convert('RGB')
a = np.asarray(im).astype(int)
r,g,b = a[:,:,0],a[:,:,1],a[:,:,2]
masks = {
 'red':   (r>110)&(r-g>50)&(r-b>50),
 'blue':  (b>90)&(b-r>25)&(b-g>15),
 'green': (g>110)&(g-r>35)&(g-b>35),
}
STATIONS=[273,297,325,356,389,428,471,520,577,641,719]

def components(mask, min_area=8):
    lab,n = ndimage.label(mask, structure=np.ones((3,3)))
    out=[]
    for i in range(1,n+1):
        sel=(lab==i); n_=int(sel.sum())
        if n_<min_area: continue
        ys,xs=np.where(sel)
        out.append([int(xs.min()),int(xs.max()),int(ys.min()),int(ys.max()),n_])
    return out

def merge(comps, rad=13):
    coms=[c[:] for c in comps]; merged=True
    while merged:
        merged=False
        for i in range(len(coms)):
            for j in range(i+1,len(coms)):
                A,B=coms[i],coms[j]
                if abs((A[0]+A[1])/2-(B[0]+B[1])/2)<rad and abs((A[2]+A[3])/2-(B[2]+B[3])/2)<rad:
                    coms[i]=[min(A[0],B[0]),max(A[1],B[1]),min(A[2],B[2]),max(A[3],B[3]),A[4]+B[4]]
                    coms.pop(j); merged=True; break
            if merged: break
    return coms

def nearest_station(cx): return min(STATIONS, key=lambda s:abs(s-cx))

def extract(mask, verbose=False):
    m=mask.copy()
    # exclude legend box (bottom-left)
    m[440:, :272]=False
    # exclude top area too? no.
    comps=merge(components(m))
    per={}
    for c in comps:
        cx=(c[0]+c[1])/2
        s=nearest_station(cx); per.setdefault(s,[]).append(c)
    result={}
    for s in sorted(per):
        markers=sorted(per[s], key=lambda c:(c[2]+c[3])/2)
        if len(markers)==1:
            result[s]=(markers[0],markers[0])
        else:
            cys=[(c[2]+c[3])/2 for c in markers]
            best_gap=0;bi=0
            for i in range(len(cys)-1):
                if cys[i+1]-cys[i]>best_gap: best_gap=cys[i+1]-cys[i];bi=i
            if best_gap>25:
                up=markers[:bi+1]; lo=markers[bi+1:]
            else: up=markers;lo=markers
            result[s]=(up[0],lo[-1])
    return result

def px2x(px): return 0.8 + (px-201.0)/(749.5-201.0)*1.0
def py2y(py):
    lv = math.log10(3.162277660168379e-8) + (py-635.5)/(99.5-635.5)*(math.log10(0.03162277660168379)-math.log10(3.162277660168379e-8))
    return 10**lv

data={}
for name in ['red','blue','green']:
    res=extract(masks[name])
    up=[]; lo=[]
    for s in sorted(res):
        um,lm=res[s]
        ucx=(um[0]+um[1])/2; ucy=(um[2]+um[3])/2
        lcx=(lm[0]+lm[1])/2; lcy=(lm[2]+lm[3])/2
        up.append([s,round(px2x(ucx),4),round(py2y(ucy),10),round(ucy,1),(um[0],um[1],um[2],um[3],um[4])])
        lo.append([s,round(px2x(lcx),4),round(py2y(lcy),10),round(lcy,1),(lm[0],lm[1],lm[2],lm[3],lm[4])])
    data[name]=(up,lo)
    print('==== %s ===='%name, '  open_pts=%d filled_pts=%d'%(len(up),len(lo)))
    print('  OPEN/bulk:')
    for u in up: print('    st%3d x=%.4f y=%.6g py=%.1f bbox=%s'%(u[0],u[1],u[2],u[3],u[4]))
    print('  FILLED/total:')
    for l in lo: print('    st%3d x=%.4f y=%.6g py=%.1f bbox=%s'%(l[0],l[1],l[2],l[3],l[4]))
