import numpy as np
from PIL import Image
im = np.array(Image.open('images/fig_092.png').convert('RGB')).astype(int)
R,G,B = im[:,:,0], im[:,:,1], im[:,:,2]
masks = {
 'blue': (B>120)&(R<120)&(G<120),
 'red':  (R>120)&(B<120)&(G<120),
 'green':(G>80)&(R<120)&(B<120),
}
def cc(mask):
    lab = np.zeros_like(mask, dtype=int); cur=0
    from collections import deque
    H,W = mask.shape
    for i in range(H):
        for j in range(W):
            if mask[i,j] and lab[i,j]==0:
                cur+=1; q=deque([(i,j)]); lab[i,j]=cur
                while q:
                    y,x=q.popleft()
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and mask[ny,nx] and lab[ny,nx]==0:
                                lab[ny,nx]=cur; q.append((ny,nx))
    return lab,cur
def blobs(name, mask, minsize):
    lab,cur = cc(mask)
    out=[]
    for k in range(1,cur+1):
        ys,xs=np.where(lab==k)
        if len(ys)>=minsize:
            out.append((round(xs.mean(),1), round(ys.mean(),1), len(ys)))
    out.sort()
    return out

# Filled markers: erode to kill 2-3px lines
for name,m in masks.items():
    mm = m.copy(); mm[:95,:]=False; mm[465:,:]=False; mm[:,:149]=False; mm[:,716:]=False
    # erosion: keep pixel if all 8 neighbors exist (3x3)
    er = mm[1:-1,1:-1].copy()
    for dy in(-1,0,1):
        for dx in(-1,0,1):
            if (dy,dx)"'!=(0,0):
                er &= mm[1+dy:-1+dy, 1+dx:-1+dx]
    erf = np.zeros_like(mm); erf[1:-1,1:-1]=er
    bl = blobs(name, erf, 2)
    print(name, '"'FILLED candidates:', len(bl))
    print(bl[:50])
EOF"

